private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    if (i < 0 || i >= bb.limit()) {
        return i; // nothing to decode
    }
    int first = bb.get(i) & 0xFF;
    int bytesCount;
    int codePoint;
    if ((first & 0x80) == 0) { // 0xxxxxxx
        codePoint = first;
        bytesCount = 1;
    } else if ((first & 0xE0) == 0xC0) { // 110xxxxx
        bytesCount = 2;
        codePoint = first & 0x1F;
    } else if ((first & 0xF0) == 0xE0) { // 1110xxxx
        bytesCount = 3;
        codePoint = first & 0x0F;
    } else if ((first & 0xF8) == 0xF0) { // 11110xxx
        bytesCount = 4;
        codePoint = first & 0x07;
    } else {
        // invalid leading byte
        sb.append('\uFFFD');
        return i + 1;
    }

    // Ensure enough bytes remain
    if (i + bytesCount > bb.limit()) {
        // incomplete sequence, append replacement and return current index + 1
        sb.append('\uFFFD');
        return i + 1;
    }

    // Validate continuation bytes and build code point
    for (int offset = 1; offset < bytesCount; offset++) {
        int b = bb.get(i + offset) & 0xFF;
        if ((b & 0xC0) != 0x80) {
            sb.append('\uFFFD');
            return i + 1; // consume only the first byte
        }
        codePoint = (codePoint << 6) | (b & 0x3F);
    }

    // Overlong encoding or invalid ranges
    if (codePoint > 0x10FFFF ||
        (codePoint >= 0xD800 && codePoint <= 0xDFFF)) {
        sb.append('\uFFFD');
    } else if (codePoint <= 0xFFFF) {
        sb.append((char) codePoint);
    } else {
        // Surrogate pair
        codePoint -= 0x10000;
        sb.append((char) (0xD800 + (codePoint >> 10)));
        sb.append((char) (0xDC00 + (codePoint & 0x3FF)));
    }
    return i + bytesCount;
}

