    if (headerPart == null || headerPart.isEmpty()){
        return -1;
    }
    int length = headerPart.length();
    // Ensure start index is within bounds
    int idx = Math.max(0, Math.min(end, length - 1));
    try {
        while (idx < length - 1) {
            if (headerPart.charAt(idx) == '\r' && headerPart.charAt(idx + 1) == '\n') {
                return idx;
            }
            idx++;
        }
    } catch (IndexOutOfBoundsException e) {
        // In case end parameter was outside the string bounds, just ignore
    }
    return -1; // Not found
}

