@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // Retrieve all vertices from the target graph
    Collection<V> verts = target.getVertices();
    if (verts == null) return;
    List<V> vertexList = new ArrayList<>(verts);
    int total = vertexList.size();
    if (total < 2) return; // Need at least two vertices to form a bipartite graph
    // Split the vertices into two parts: left and right
    int mid = total / 2;
    List<V> left = vertexList.subList(0, mid);
    List<V> right = vertexList.subList(mid, total);
    // Connect every vertex in the left part with every vertex in the right part
    for (V u : left) {
        for (V v : right) {
            try {
                target.addEdge(u, v);
            } catch (Exception e) {
                // Ignore edge-adding failures or log if necessary
            }
        }
    }
    // Store a reference to one vertex from each part in the result map
    if (!left.isEmpty() && !right.isEmpty()) {
        resultMap.put("left", left.get(0));
        resultMap.put("right", right.get(0));
    }
}

