public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pt = (ParameterizedType) genericType;
    Type[] args = pt.getActualTypeArguments();
    Class<?>[] result = new Class<?>[args.length];

    Map<TypeVariable<?>, Type> typeVariableMap = buildTypeVariableMap(targetType);

    for (int i = 0; i < args.length; i++) {
        Class<?> resolved = resolveToClass(args[i], typeVariableMap);
        if (resolved == null) {
            return null;
        }
        result[i] = resolved;
    }
    return result;
}

private static Map<TypeVariable<?>, Type> buildTypeVariableMap(Class<?> type) {
    Map<TypeVariable<?>, Type> map = new HashMap<>();

    while (type != null) {
        Type genericSuper = type.getGenericSuperclass();
        if (genericSuper instanceof ParameterizedType) {
            ParameterizedType superPT = (ParameterizedType) genericSuper;
            TypeVariable<?>[] superParams = superPT.getRawType().getTypeParameters();
            Type[] superArgs = superPT.getActualTypeArguments();

            for (int i = 0; i < superParams.length; i++) {
                map.put(superParams[i], superArgs[i]);
            }
        }
        type = type.getSuperclass();
    }

    return map;
}

private static Class<?> resolveToClass(Type type, Map<TypeVariable<?>, Type> map) {
    if (type instanceof Class<?>) {
        return (Class<?>) type;
    }
    if (type instanceof ParameterizedType) {
        return (Class<?>) ((ParameterizedType) type).getRawType();
    }
    if (type instanceof TypeVariable<?>) {
        Type actual = map.get(type);
        if (actual == null) {
            return null;
        }
        return resolveToClass(actual, map);
    }
    return null;
}

@Override public void accept(final METRICS data){
    if (data == null) {
        return;
    }
    try {
        // Assume METRICS implements a method getKey() that returns a unique key for the metric
        Object key = data.getKey();
        METRICS existing = cache.get(key);
        if (existing != null) {
            try {
                // Prefer a merge operation if available
                existing.merge(data);
            } catch (NoSuchMethodError ignored) {
                // Fallback: replace the existing entry if merge is not defined
                cache.put(key, data);
            }
        } else {
            cache.put(key, data);
        }
    } catch (Exception e) {
        // If getKey() or merge() are not available, fall back to using data's toString() as the key
        try {
            String key = data.toString();
            METRICS existing = cache.get(key);
            if (existing != null) {
                try {
                    existing.merge(data);
                } catch (Exception ignored) {
                    cache.put(key, data);
                }
            } else {
                cache.put(key, data);
            }
        } catch (Exception ex) {
            // As a last resort, ignore the data to avoid crashing
        }
    }
}

