public long readLong(final int offset){
    try {
        if (offset < 0 || offset + 8 > this.bytes.length) {
            throw new ArrayIndexOutOfBoundsException("offset out of bounds");
        }
        return ((long)(this.bytes[offset] & 0xFF) << 56)
             | ((long)(this.bytes[offset+1] & 0xFF) << 48)
             | ((long)(this.bytes[offset+2] & 0xFF) << 40)
             | ((long)(this.bytes[offset+3] & 0xFF) << 32)
             | ((long)(this.bytes[offset+4] & 0xFF) << 24)
             | ((long)(this.bytes[offset+5] & 0xFF) << 16)
             | ((long)(this.bytes[offset+6] & 0xFF) << 8)
             | ((long)(this.bytes[offset+7] & 0xFF));
    } catch (ArrayIndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Invalid offset: " + offset, e);
    }
}

public boolean equals(final byte[] data,int offset,final int len){
    // The internal array is assumed to be stored in a field named `data`
    // to avoid name clash with the parameter, we explicitly reference it via `this`.
    if (data == null || offset < 0 || len < 0) {
        return false;
    }
    // Ensure the slice is within the bounds of the provided array.
    if (offset + len > data.length) {
        return false;
    }
    byte[] internalArray = this.data;
    if (internalArray == null) {
        // If the internal array is null, only consider it equal when len == 0
        return len == 0;
    }
    // The lengths must match exactly for equality.
    if (internalArray.length != len) {
        return false;
    }
    // Compare each element of the internal array with the corresponding element
    // of the provided slice.
    for (int i = 0; i < len; i++) {
        if (internalArray[i] != data[offset + i]) {
            return false;
        }
    }
    return true;
}

