static long compressTimeBucket(long timeBucket,int dayStep){
    if (dayStep <= 0) {
        return timeBucket;
    }
    long year = timeBucket / 10000L;
    long month = (timeBucket % 10000L) / 100L;
    long day = timeBucket % 100L;
    if (day < 1L) {
        return timeBucket;
    }
    long bucketStartDay = ((day - 1L) / dayStep) * dayStep + 1L;
    return year * 10000L + month * 100L + bucketStartDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len){
    if (str == null) {
        return 0;
    }
    if (index < 0 || len < 0 || index > str.length() || index + len > str.length()) {
        throw new IndexOutOfBoundsException("index or len out of bounds");
    }
    int end = index + len;
    int count = 0;
    int i = index;
    while (i < end) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            count++;
        } else if (ch <= 0x7FF) {
            count += 2;
        } else if (ch >= 0xD800 && ch <= 0xDFFF) { // surrogate
            if (Character.isHighSurrogate(ch) && i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
                // Valid surrogate pair
                count += 4;
                i++; // skip the low surrogate
            } else {
                // Invalid surrogate, encode as 3 bytes each
                count += 3;
            }
        } else {
            count += 3;
        }
        i++;
    }
    return count;
}

