private Set<V> initVisibleVertices(){
    Set<V> visible = new HashSet<>();
    if (edges == null) return visible;
    for (E e : edges){
        if (e == null) continue;
        try{
            V src = e.getSource();
            V dst = e.getTarget();
            if (src != null) visible.add(src);
            if (dst != null) visible.add(dst);
        }catch(Exception ignored){
            // Fallback for edges stored as array of vertex identifiers
            if (e instanceof Object[]){
                Object[] arr = (Object[]) e;
                if (arr.length >= 2){
                    @SuppressWarnings("unchecked")
                    V src = (V) arr[0];
                    @SuppressWarnings("unchecked")
                    V dst = (V) arr[1];
                    if (src != null) visible.add(src);
                    if (dst != null) visible.add(dst);
                }
            }
        }
    }
    return visible;
}

