    if (type != Character.class && type != char.class) {
        throw new Exception("Unsupported target type: " + type.getName());
    }

    // Null values can be safely returned as null
    if (value == null) {
        return null;
    }

    // If the value is already a Character, return it directly
    if (value instanceof Character) {
        return value;
    }

    // Convert from String of length 1
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return str.charAt(0);
        } else {
            throw new Exception("Cannot convert String of length " + str.length() + " to Character");
        }
    }

    // Convert from Number by treating the numeric value as a char code
    if (value instanceof Number) {
        int intValue = ((Number) value).intValue();
        return (char) intValue;
    }

    // Convert from char array of length 1
    if (value instanceof char[]) {
        char[] arr = (char[]) value;
        if (arr.length == 1) {
            return arr[0];
        } else {
            throw new Exception("Cannot convert char array of length " + arr.length + " to Character");
        }
    }

    // Unsupported input type
    throw new Exception("Cannot convert value of type " + value.getClass().getName() + " to Character");
}

