                        int octal = 0;
                        int j = i + 1;
                        int digits = 0;
                        while (j < str.length() && digits < 3 && str.charAt(j) >= '0' && str.charAt(j) <= '7') {
                            octal = (octal << 3) + (str.charAt(j) - '0');
                            j++;
                            digits++;
                        }
                        sb.append((char) octal);
                        i = j - 1;
                    } else {
                        // Unrecognized escape, keep as is
                        sb.append(next);
                        i++;
                    }
                    break;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

