        }
    }
    return builder.build();
}

protected int removeUnusedNodes(){
    // Assumes a root node named 'root' of type Category is available in this class
    if (root == null) {
        return 0;
    }
    int removedCount = 0;
    Deque<Category> stack = new ArrayDeque<>();
    stack.push(root);
    try {
        while (!stack.isEmpty()) {
            Category current = stack.pop();
            // Retrieve children; if a node has no children method, skip
            List<Category> children = current.getChildren();
            if (children == null) {
                continue;
            }
            Iterator<Category> it = children.iterator();
            while (it.hasNext()) {
                Category child = it.next();
                try {
                    if (!child.isActive()) {
                        // Remove inactive child from the parent's children list
                        it.remove();
                        removedCount++;
                    } else {
                        // Continue traversal with active child
                        stack.push(child);
                    }
                } catch (RuntimeException ex) {
                    // Skip problematic child; optionally log if logger available
                }
            }
        }
    } catch (RuntimeException ex) {
        // If the root itself is problematic, return -1 as an error indicator
        return -1;
    }
    return removedCount;
}

