int addConstantNameAndType(final String name, final String descriptor) {
    // First, check if the (name,descriptor) pair already exists
    int existing = findNameAndType(name, descriptor);
    if (existing != NOT_FOUND) {
        return existing;
    }

    // Ensure the name and descriptor UTF‑8 entries exist in the pool
    int nameIdx = findUtf8(name);
    if (nameIdx == NOT_FOUND) {
        nameIdx = addUtf8(name);
    }
    int descIdx = findUtf8(descriptor);
    if (descIdx == NOT_FOUND) {
        descIdx = addUtf8(descriptor);
    }

    // Grow the pool if necessary
    if (endOfPool + 1 >= maxPoolSize) {
        ensureCapacity();
    }

    // Add the CONSTANT_NameAndType_info entry
    endOfPool++;
    types[endOfPool] = NAME_AND_TYPE;          // tag value 12
    byteCode[offsets[endOfPool]++] = (byte) (nameIdx >> 8);
    byteCode[offsets[endOfPool]++] = (byte) (nameIdx & 0xFF);
    byteCode[offsets[endOfPool]++] = (byte) (descIdx >> 8);
    byteCode[offsets[endOfPool]++] = (byte) (descIdx & 0xFF);

    return endOfPool;
}

private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    StringBuilder result = new StringBuilder(input.length());
    int length = input.length();
    for (int i = 0; i < length; i++) {
        char current = input.charAt(i);
        if (current == '\\') {
            if (i + 1 < length) {
                // Append the escaped character and skip it
                result.append(input.charAt(i + 1));
                i++;
            } // else trailing backslash: ignore
        } else {
            result.append(current);
        }
    }
    return result.toString();
}

