    if (nameStart < 0) {
        nameStart = 0;
    }
    if (nameStart >= len) {
        return;
    }
    int i = nameStart;
    while (i < len) {
        // Skip any whitespace
        while (i < len && Character.isWhitespace(name.charAt(i))) {
            i++;
        }
        if (i >= len) {
            break;
        }
        // Append the first non-whitespace character of the word
        buf.append(name.charAt(i));
        // Move to the end of the current word
        while (i < len && !Character.isWhitespace(name.charAt(i))) {
            i++;
        }
    }
}

