public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("path and relativePath must not be null");
    }
    if (relativePath.isEmpty()) {
        return path;
    }

    // Split the base path into components, preserving a leading slash flag
    boolean leadingSlash = path.startsWith("/");
    String[] baseTokens = path.split("/", -1);
    java.util.ArrayList<String> baseSegments = new java.util.ArrayList<>();
    for (String token : baseTokens) {
        if (token.isEmpty()) {
            continue;
        }
        baseSegments.add(token);
    }

    // Process the relative path components
    String[] relTokens = relativePath.split("/", -1);
    for (String token : relTokens) {
        if (token.isEmpty() || token.equals(".")) {
            continue; // skip empty or current dir
        }
        if (token.equals("..")) {
            if (!baseSegments.isEmpty()) {
                baseSegments.remove(baseSegments.size() - 1);
            }
            continue;
        }
        baseSegments.add(token);
    }

    // Build the resulting path string
    StringBuilder result = new StringBuilder();
    if (leadingSlash) {
        result.append('/');
    }
    for (int i = 0; i < baseSegments.size(); i++) {
        if (i > 0) {
            result.append('/');
        }
        result.append(baseSegments.get(i));
    }

    // Handle the case where all segments were removed (e.g. path "/" with relative "../")
    if (result.length() == 0 && leadingSlash) {
        return "/";
    }
    if (result.length() == 0) {
        return ".";
    }

    return result.toString();
}

